import java.util.*;

class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        int a = sc.nextInt();
        Set<Integer> badminton = getBadmintonList(a);
        System.out.println(badminton.size() + " " + badminton);

        int b = sc.nextInt();
        Set<Integer> basketball = getBasketballList(b);
        System.out.println(basketball.size() + " " + basketball);

        Set<Integer> any = new TreeSet<>(badminton);
        any.addAll(basketball);
        System.out.println(any.size() + " " + any);

        Set<Integer> both = new TreeSet<>(badminton);
        both.retainAll(basketball);
        System.out.println(both.size() + " " + both);

        Set<Integer> neither = new TreeSet<>();
        for (int i = 1; i <= 1000; i++) {
            if (!badminton.contains(i) && !basketball.contains(i)) {
                neither.add(i);
            }
        }
        System.out.println(neither.size() + " " + neither);

        sc.close();
    }
    public static Set<Integer> getBadmintonList(int seed) {
        // 创建包含1-1000的列表
        List<Integer> numbers = new ArrayList<>(1000);
        for (int i = 1; i <= 1000; i++) {
            numbers.add(i);
        }

        // 使用指定种子打乱顺序
        Collections.shuffle(numbers, new Random(seed));

        // 取前300个元素
        return new TreeSet<>(numbers.subList(0, 300));
    }

    public static Set<Integer> getBasketballList(int seed) {
        // 创建包含1-1000的列表
        List<Integer> numbers = new ArrayList<>(1000);
        for (int i = 1; i <= 1000; i++) {
            numbers.add(i);
        }

        // 使用指定种子打乱顺序
        Collections.shuffle(numbers, new Random(seed));

        // 取前400个元素并返回有序集合
        return new TreeSet<>(numbers.subList(0, 400));
    }
}
